<script setup lang="ts">
import { computed, ref } from 'vue'
import { Activity, Bell, Check, ChevronRight, CircleAlert, CircleCheck, Home, LayoutDashboard, Lightbulb, LogOut, Menu, Package, Radio, Settings2, Thermometer, Wifi, WifiOff, X, Zap } from 'lucide-vue-next'
import { usePlatform } from './services/usePlatform'
import { canControl, commandStatusLabel, confirmationLabel, updateAlarmStatus } from './domain/platform'
import type { AlarmRule, Device, PlatformState, Product } from './domain/types'

const platform = usePlatform()
const view = ref('dashboard')
const query = ref('')
const selectedDeviceId = ref('')
const selectedAlarmId = ref('')
const showProductForm = ref(false)
const showRuleForm = ref(false)
const mobileMenu = ref(false)
const toast = ref('')
const productDraft = ref<Product>(newProduct())
const ruleDraft = ref<AlarmRule>(newRule())

const state = computed(() => platform.state.value)
const selectedDevice = computed(() => state.value.devices.find((device) => device.id === selectedDeviceId.value))
const selectedAlarm = computed(() => state.value.alarms.find((alarm) => alarm.id === selectedAlarmId.value))
const onlineCount = computed(() => state.value.devices.filter((device) => device.enabled && device.online).length)
const activeAlarms = computed(() => state.value.alarms.filter((alarm) => alarm.status !== 'closed'))
const filteredDevices = computed(() => state.value.devices.filter((device) => `${device.name} ${device.code} ${device.location}`.toLowerCase().includes(query.value.toLowerCase())))
const currentTitle = computed(() => ({ dashboard: '总览', devices: '设备', alarms: '告警中心', products: '产品与属性', settings: '接入与设置' }[view.value] ?? '总览'))

function newProperty() { return { id: crypto.randomUUID(), name: '', key: '', type: 'number' as const, unit: '' } }
function newProduct(): Product { return { id: '', name: '', category: '环境监测', description: '', status: 'draft', protocol: 'MQTT', properties: [newProperty()], createdAt: new Date().toISOString() } }
function newRule(): AlarmRule { return { id: '', name: '', deviceId: 'all', property: 'temperature', operator: 'gt', threshold: 30, level: 'warning', enabled: true } }
function notify(message: string) { toast.value = message; window.setTimeout(() => { toast.value = '' }, 2800) }
function go(next: string) { view.value = next; mobileMenu.value = false }
function login() { platform.login('lin.yuan@example.com', 'openiot'); notify('欢迎回来，设备状态已同步') }
function productName(device: Device) { return state.value.products.find((product) => product.id === device.productId)?.name ?? '未知产品' }
function relativeTime(value: string) { const minutes = Math.max(0, Math.floor((Date.now() - new Date(value).getTime()) / 60000)); return minutes < 1 ? '刚刚' : minutes < 60 ? `${minutes} 分钟前` : `${Math.floor(minutes / 60)} 小时前` }
function openDevice(device: Device) { selectedDeviceId.value = device.id }
function control(device: Device, target: string) { platform.controlDevice(device.id, target); notify(device.confirmation === 'gateway' ? '红外网关已发送，目标设备状态未确认' : '命令已发送，等待设备确认') }
function ackAlarm(action: 'acknowledge' | 'close') { const alarm = selectedAlarm.value; if (!alarm) return; platform.update((current) => ({ ...current, alarms: current.alarms.map((item) => item.id === alarm.id ? updateAlarmStatus(item, action, '') : item) })); selectedAlarmId.value = ''; notify(action === 'acknowledge' ? '告警已确认' : '告警已关闭') }
function saveProduct() { if (!productDraft.value.name.trim() || productDraft.value.properties.some((property) => !property.name.trim() || !property.key.trim())) return notify('请完整填写产品和属性'); platform.addProduct({ name: productDraft.value.name, category: productDraft.value.category, description: productDraft.value.description, status: productDraft.value.status, properties: productDraft.value.properties }); showProductForm.value = false; notify('产品已创建') }
function saveRule() { if (!ruleDraft.value.name.trim()) return notify('请输入规则名称'); platform.saveRule({ ...ruleDraft.value, id: ruleDraft.value.id || crypto.randomUUID() }); showRuleForm.value = false; notify('告警规则已保存') }
</script>

<template>
  <main v-if="!state.user" class="stable-login"><section class="login-art"><span class="brand"><Activity :size="19"/> OpenIOT</span><div><span class="eyebrow">家庭设备控制台</span><h1>让每一台设备，<em>清晰地工作。</em></h1><p>在一个安静、可靠的空间里，查看设备状态、控制家庭环境，并及时处理异常。</p></div><span class="art-note"><CircleCheck :size="16"/> 数据留在家庭网络内</span></section><form class="login-box" @submit.prevent="login"><span class="eyebrow">欢迎回来</span><h2>登录控制台</h2><p>登录后管理你家的设备与数据。</p><label>邮箱地址<input value="lin.yuan@example.com" type="email"/></label><label>密码<input value="openiot" type="password"/></label><button class="primary" type="submit">进入控制台 <ChevronRight :size="16"/></button><small class="muted">演示账号可直接使用预填信息登录</small></form></main>
  <div v-else class="stable-shell"><div class="mobile-cover" :class="{ show: mobileMenu }" @click="mobileMenu = false"></div><aside class="stable-sidebar" :class="{ open: mobileMenu }"><div class="stable-logo"><span class="brand-mark"><Activity :size="17"/></span><strong>OpenIOT</strong><button class="icon-btn close-menu" @click="mobileMenu = false"><X :size="17"/></button></div><div class="home-chip"><Home :size="15"/><span><b>林远的家</b><small>本地家庭网络</small></span></div><nav><button :class="{ active: view === 'dashboard' }" @click="go('dashboard')"><LayoutDashboard :size="17"/>总览</button><button :class="{ active: view === 'devices' }" @click="go('devices')"><Radio :size="17"/>设备</button><button :class="{ active: view === 'alarms' }" @click="go('alarms')"><Bell :size="17"/>告警中心 <b v-if="activeAlarms.length">{{ activeAlarms.length }}</b></button><span>管理</span><button :class="{ active: view === 'products' }" @click="go('products')"><Package :size="17"/>产品与属性</button><button :class="{ active: view === 'settings' }" @click="go('settings')"><Settings2 :size="17"/>接入与设置</button></nav><div class="side-bottom"><span class="broker-dot"><i></i> MQTT 连接正常</span><button class="user-line" @click="go('settings')"><span class="avatar">林</span><span><b>林远</b><small>管理员</small></span></button><button class="logout" @click="platform.logout()"><LogOut :size="14"/>退出登录</button></div></aside><section class="stable-main"><header class="stable-top"><button class="icon-btn mobile-trigger" @click="mobileMenu = true"><Menu :size="19"/></button><span>林远的家 <ChevronRight :size="14"/> {{ currentTitle }}</span><div><span class="lan-status"><i></i>局域网已连接</span><button class="icon-btn" @click="go('alarms')"><Bell :size="18"/></button><span class="avatar">林</span></div></header><div class="stable-content"><div class="stable-breadcrumb">OpenIOT / {{ currentTitle }} <span><i></i>数据已同步</span></div>
    <section v-if="view === 'dashboard'" class="stable-page"><div class="page-intro"><div><span class="eyebrow">家庭设备运行正常</span><h1>早上好，林远</h1><p>这是你家设备今天的运行概况。</p></div></div><div class="kpi-grid"><button @click="go('devices')"><Radio :size="18"/><small>设备总数</small><strong>{{ state.devices.length }}<em> 台</em></strong><span>{{ state.products.length }} 个产品</span></button><button @click="go('devices')"><Wifi :size="18"/><small>当前在线</small><strong>{{ onlineCount }}<em> / {{ state.devices.filter((d) => d.enabled).length }} 台</em></strong><span>连接稳定</span></button><button @click="go('alarms')"><Bell :size="18"/><small>待处理告警</small><strong>{{ activeAlarms.length }}<em> 条</em></strong><span>需要关注</span></button><button @click="state.devices.find((d) => d.state.temperature !== undefined) && openDevice(state.devices.find((d) => d.state.temperature !== undefined)!)"><Thermometer :size="18"/><small>室内温度</small><strong>{{ state.devices.find((d) => d.state.temperature !== undefined)?.state.temperature ?? '--' }}<em> °C</em></strong><span>湿度 {{ state.devices.find((d) => d.state.humidity !== undefined)?.state.humidity ?? '--' }}%</span></button></div><div class="stable-columns"><article class="stable-panel chart-panel"><header><div><span class="eyebrow">环境监测</span><h2>室内温度</h2></div><span class="panel-note">最近 24 小时</span></header><div class="big-reading">{{ state.devices.find((d) => d.state.temperature !== undefined)?.state.temperature ?? '--' }}<small>°C</small><span>较昨日低 0.8°</span></div><div class="fake-chart"><span v-for="n in 12" :key="n" :style="{ height: `${42 + Math.sin(n / 1.7) * 22 + n * 1.4}%` }"></span></div><div class="chart-axis"><span>00:00</span><span>06:00</span><span>12:00</span><span>18:00</span><span>现在</span></div></article><article class="stable-panel"><header><div><span class="eyebrow">空间状态</span><h2>家庭设备</h2></div><button class="link-btn" @click="go('devices')">查看全部 <ChevronRight :size="14"/></button></header><button v-for="device in state.devices.filter((d) => d.enabled).slice(0, 4)" :key="device.id" class="device-mini" @click="openDevice(device)"><span class="device-icon" :class="device.confirmation === 'gateway' ? 'orange' : device.state.temperature !== undefined ? 'blue' : 'green'"><Thermometer v-if="device.state.temperature !== undefined" :size="17"/><Radio v-else-if="device.confirmation === 'gateway'" :size="17"/><Lightbulb v-else :size="17"/></span><span><b>{{ device.name }}</b><small>{{ device.location }} · {{ productName(device) }}</small></span><span class="device-state" :class="device.online ? 'on' : 'off'"><i></i>{{ device.online ? '在线' : '离线' }}</span><ChevronRight :size="15"/></button></article></div></section>
    <section v-else-if="view === 'devices'" class="stable-page"><div class="page-intro"><div><span class="eyebrow">平台 / 设备管理</span><h1>设备</h1><p>查看家庭设备状态、数据与控制记录。</p></div></div><div class="toolbar"><label><Radio :size="16"/><input v-model="query" placeholder="搜索设备名称、编号或位置"/></label><span>{{ filteredDevices.length }} 台设备 · {{ onlineCount }} 台在线</span></div><article class="stable-panel table-panel"><div class="table-head"><b>所有设备</b><span>状态、数据与确认能力</span></div><div class="table-row table-label"><span>设备</span><span>产品</span><span>状态</span><span>当前数据</span><span>确认能力</span><span></span></div><button v-for="device in filteredDevices" :key="device.id" class="table-row" @click="openDevice(device)"><span class="table-device"><span class="device-icon small" :class="device.confirmation === 'gateway' ? 'orange' : 'green'"><Radio :size="15"/></span><span><b>{{ device.name }}</b><small>{{ device.code }} · {{ device.location }}</small></span></span><span>{{ productName(device) }}</span><span class="device-state" :class="device.enabled && device.online ? 'on' : 'off'"><i></i>{{ !device.enabled ? '已停用' : device.online ? '在线' : '离线' }}</span><span><b>{{ typeof device.state.temperature === 'number' ? `${device.state.temperature} °C` : typeof device.state.power === 'boolean' ? (device.state.power ? '已开启' : '已关闭') : '状态未确认' }}</b><small>{{ relativeTime(device.lastSeen) }}</small></span><span class="capability">{{ confirmationLabel(device.confirmation) }}</span><ChevronRight :size="15"/></button></article></section>
    <section v-else-if="view === 'alarms'" class="stable-page"><div class="page-intro"><div><span class="eyebrow">平台 / 运维管理</span><h1>告警中心</h1><p>处理设备离线、属性超限和未确认状态。</p></div><button class="secondary" @click="showRuleForm = true"><Zap :size="15"/>新建告警规则</button></div><div class="alarm-kpis"><button @click="state.alarms = state.alarms"><CircleAlert :size="17"/><span>待处理</span><strong>{{ state.alarms.filter((a) => a.status === 'active').length }}</strong></button><button><CircleCheck :size="17"/><span>已确认</span><strong>{{ state.alarms.filter((a) => a.status === 'acknowledged').length }}</strong></button><button><WifiOff :size="17"/><span>紧急告警</span><strong>{{ state.alarms.filter((a) => a.level === 'critical' && a.status !== 'closed').length }}</strong></button></div><article class="stable-panel alarm-panel"><div class="tab-line"><button class="active">告警记录 {{ state.alarms.length }}</button><button @click="showRuleForm = true">告警规则 {{ state.rules.length }}</button></div><button v-for="alarm in state.alarms" :key="alarm.id" class="alarm-line" @click="selectedAlarmId = alarm.id"><span class="alarm-icon" :class="alarm.level"><CircleAlert :size="17"/></span><span><b>{{ alarm.ruleName }}</b><small>{{ alarm.deviceName }} · {{ alarm.message }}</small></span><span class="alarm-status" :class="alarm.status"><i></i>{{ alarm.status === 'active' ? '待处理' : alarm.status === 'acknowledged' ? '已确认' : '已关闭' }}</span><small>{{ relativeTime(alarm.createdAt) }}</small><ChevronRight :size="15"/></button></article></section>
    <section v-else-if="view === 'products'" class="stable-page"><div class="page-intro"><div><span class="eyebrow">平台 / 设备模型</span><h1>产品与属性</h1><p>定义一类设备的共同能力。</p></div><button class="primary" @click="showProductForm = true"><Package :size="15"/>新建产品</button></div><div class="product-grid"><button v-for="product in state.products" :key="product.id" class="product-card"><span class="device-icon blue"><Package :size="18"/></span><b>{{ product.name }}</b><small>{{ product.category }} · {{ state.devices.filter((d) => d.productId === product.id).length }} 台设备</small><span>{{ product.properties.length }} 个属性 · MQTT</span></button></div></section>
    <section v-else class="stable-page"><div class="page-intro"><div><span class="eyebrow">平台 / 系统配置</span><h1>接入与设置</h1><p>管理家庭 MQTT 连接和基础平台信息。</p></div></div><article class="stable-panel settings-panel"><header><div><span class="eyebrow">消息接入</span><h2>MQTT Broker</h2><p>设备状态与遥测通过本地 MQTT Broker 进入平台。</p></div><span class="device-state on"><i></i>连接正常</span></header><div class="settings-grid"><label>Broker 地址<input :value="state.mqtt.host"/></label><label>端口<input :value="state.mqtt.port"/></label><label>平台客户端 ID<input :value="state.mqtt.clientId"/></label></div><div class="setting-callout"><CircleCheck :size="17"/><span><b>家庭局域网访问</b><small>当前演示数据保存在浏览器本地，后续可接入 Spring Boot、PostgreSQL 与真实 MQTT Broker。</small></span></div></article></section></div></section></div>
    <Teleport to="body"><div v-if="selectedDevice" class="modal-backdrop" @click.self="selectedDeviceId = ''"><section class="modal-card"><header><div><span class="eyebrow">{{ productName(selectedDevice) }} · {{ selectedDevice.code }}</span><h2>{{ selectedDevice.name }}</h2></div><button class="icon-btn" @click="selectedDeviceId = ''"><X :size="18"/></button></header><p>{{ selectedDevice.description }}</p><div class="detail-status"><span class="device-icon large" :class="selectedDevice.confirmation === 'gateway' ? 'orange' : 'green'"><Radio :size="22"/></span><span><b>{{ selectedDevice.online ? '在线' : '离线' }}</b><small>最近通信 {{ relativeTime(selectedDevice.lastSeen) }}</small></span><span class="capability">{{ confirmationLabel(selectedDevice.confirmation) }}</span></div><div v-if="selectedDevice.confirmation === 'state' && typeof selectedDevice.state.power === 'boolean'" class="control-box"><span><b>{{ selectedDevice.state.power ? '已开启' : '已关闭' }}</b><small>设备回报的实际状态</small></span><button class="primary" :disabled="!canControl(selectedDevice)" @click="control(selectedDevice, selectedDevice.state.power ? '关闭' : '开启')">{{ selectedDevice.state.power ? '关闭' : '开启' }}</button></div><div v-else class="control-box"><span><b>红外控制</b><small>家电实际状态未确认</small></span><div><button class="secondary" :disabled="!canControl(selectedDevice)" @click="control(selectedDevice, '开启')">开机</button><button class="secondary" :disabled="!canControl(selectedDevice)" @click="control(selectedDevice, '设置 24°C 制冷')">24° 制冷</button></div></div><div class="telemetry"><div v-for="(value, key) in selectedDevice.state" :key="key"><small>{{ key }}</small><b>{{ value }}</b></div></div><h3>最近命令</h3><div v-for="command in state.commands.filter((c) => c.deviceId === selectedDevice?.id).slice(0, 4)" :key="command.id" class="command-line"><span>{{ command.target }}</span><small>{{ commandStatusLabel(command.status) }} · {{ command.message }}</small></div></section></div><div v-if="selectedAlarm" class="modal-backdrop" @click.self="selectedAlarmId = ''"><section class="modal-card"><header><div><span class="eyebrow">告警详情</span><h2>{{ selectedAlarm.ruleName }}</h2></div><button class="icon-btn" @click="selectedAlarmId = ''"><X :size="18"/></button></header><div class="detail-status"><span class="alarm-icon large" :class="selectedAlarm.level"><CircleAlert :size="21"/></span><span><b>{{ selectedAlarm.message }}</b><small>{{ selectedAlarm.deviceName }} · {{ relativeTime(selectedAlarm.createdAt) }}</small></span><span class="alarm-status" :class="selectedAlarm.status">{{ selectedAlarm.status === 'active' ? '待处理' : selectedAlarm.status === 'acknowledged' ? '已确认' : '已关闭' }}</span></div><div class="modal-actions"><button class="secondary" @click="selectedAlarmId = ''">稍后处理</button><button v-if="selectedAlarm.status === 'active'" class="primary" @click="ackAlarm('acknowledge')"><Check :size="15"/>确认告警</button><button v-if="selectedAlarm.status !== 'closed'" class="primary" @click="ackAlarm('close')">关闭告警</button></div></section></div><div v-if="showProductForm" class="modal-backdrop" @click.self="showProductForm = false"><section class="modal-card"><header><div><span class="eyebrow">设备模型</span><h2>新建产品</h2></div><button class="icon-btn" @click="showProductForm = false"><X :size="18"/></button></header><label>产品名称<input v-model="productDraft.name" placeholder="例如：空气质量传感器"/></label><label>产品分类<select v-model="productDraft.category"><option>环境监测</option><option>开关控制</option><option>红外网关</option></select></label><label>产品描述<textarea v-model="productDraft.description" rows="2"></textarea></label><div v-for="property in productDraft.properties" :key="property.id" class="property-editor"><input v-model="property.name" placeholder="属性名称"/><input v-model="property.key" placeholder="标识符，如 temperature"/><input v-model="property.unit" placeholder="单位"/></div><button class="secondary" @click="productDraft.properties.push(newProperty())">+ 添加属性</button><div class="modal-actions"><button class="secondary" @click="showProductForm = false">取消</button><button class="primary" @click="saveProduct">保存产品</button></div></section></div><div v-if="showRuleForm" class="modal-backdrop" @click.self="showRuleForm = false"><section class="modal-card"><header><div><span class="eyebrow">告警配置</span><h2>新建告警规则</h2></div><button class="icon-btn" @click="showRuleForm = false"><X :size="18"/></button></header><label>规则名称<input v-model="ruleDraft.name" placeholder="例如：室温偏高"/></label><label>属性<select v-model="ruleDraft.property"><option value="temperature">温度</option><option value="humidity">湿度</option><option value="energy">累计电量</option></select></label><label>阈值<input v-model.number="ruleDraft.threshold" type="number"/></label><div class="modal-actions"><button class="secondary" @click="showRuleForm = false">取消</button><button class="primary" @click="saveRule">保存规则</button></div></section></div></Teleport><Transition name="toast"><div v-if="toast" class="toast">{{ toast }}</div></Transition>
  </div>
</template>
